+  'ado_create_work_item': {
+    'workItemType': ['workItemType', 'issueType', 'type'],
+    'title': ['title', 'summary'],
+    'description': ['description', 'body'],
+  },
+  'github_create_comment': {
+    'body': ['body', 'text', 'comment'],
+    'pullRequestId': ['pullRequestId', 'number', 'issueNumber'],
+  },
+};
